float sdStairs(vec2 p)
{
    float l = (p.x + p.y) * 0.5;
    vec2 k = p - vec2(floor(l), ceil(l));
    vec2 k2 = p - vec2(floor(l + 0.5), floor(l + 0.5));
    float d = length(vec2(min(k.x, 0.0), max(k.y, 0.0)));
    float d2 = length(vec2(max(k2.x, 0.0), min(k2.y, 0.0)));
    return (d - d2);
}

float sdStairs(vec2 p, float h)
{
    p.xy = p.y < p.x ? p.yx : p.xy;
    return sdStairs(p - vec2(0.0, h));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;

    float d = sdStairs(p * 3.0, 1.0) / 3.0;

    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
    col *= 1.0 - exp(-7.0*abs(d));
    col *= 0.8 + 0.2 * cos(160.0*abs(d));
    col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.015,abs(d)) );

	fragColor = vec4(col, 1.0);
}
